273	// Aggregate is a session's usage built from successive deltas. It is not safe
274	// for concurrent use: one goroutine (Bubble Tea's Update) owns it.
275	type Aggregate struct {
276		parent    string
277		id, seq   uint64
278		fresh     bool
279		sessionID string
280		files     []fileCursor // parent first, then sub-agents by rank
281		metas     []metaCursor
