299	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
300	func (a *Aggregate) Cursor() Cursor {
301		return Cursor{
302			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
303			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
304		}
305	}
306	
307	// Apply folds d in, or replaces everything with it when d.Full(). It returns
308	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
309	// takes ownership of d.
310	func (a *Aggregate) Apply(d Delta) error {
311		if !d.valid || d.id != a.id || d.seq != a.seq {
312			return ErrStaleDelta
313		}
314		switch {
315		case d.full:
316			a.t = boundedTable(d.part)
317		case d.part != nil:
318			a.t.mergeCapped(d.part)
319		}
320		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
321		a.fresh = false
322		a.seq++
323		return nil
324	}
