326	// boundedTable returns part, or a copy of it holding at most maxNoIDEntries
327	// entries without a message id.
328	func boundedTable(part *table) *table {
329		if part == nil {
330			return newTable()
331		}
332		if part.noID <= maxNoIDEntries {
333			return part
334		}
335		t := newTable()
336		t.mergeCapped(part)
337		return t
338	}
