368	// subAgent builds a sub-agent's identity from its meta cursor, counting a
369	// missing or unreadable meta file in diag.
370	func subAgent(fc fileCursor, m metaCursor, diag *Diagnostics) Agent {
371		ag := Agent{ID: fc.label, key: fc.rank}
372		switch {
373		case m.path == "":
374			diag.MetaMissing++
375		case m.unreadable:
376			diag.MetaUnreadable++
377		default:
378			ag.Type, ag.State, ag.SpawnDepth = m.typ, m.state, m.depth
379		}
380		return ag
381	}
