383	// ReadDelta lists the session again (parent, subagents/, meta files, Lstat
384	// only) and reads what was appended since c. Files whose size did not change
385	// are not opened. It fails only if the parent transcript is missing, a link,
386	// not a regular file, or the session cannot be listed; errors name base names
387	// only. On error there is nothing to apply.
388	func ReadDelta(c Cursor) (Delta, error) {
389		files, infos, err := listForPoll(c.parent)
390		if err != nil {
391			return Delta{}, err
392		}
393		return readSession(files, infos, c, timeNow()), nil
394	}
