433	// readSession reads the files of a listing from c. A change that is not an
434	// append (D4) restarts every file from the start and the delta is Full.
435	// ParseSession passes a fresh cursor and no meta Lstat information.
436	func readSession(files SessionFiles, infos map[string]os.FileInfo, c Cursor, now time.Time) Delta {
437		targets := sessionTargets(files)
438		full := c.fresh
439		p, ok := readTargets(targets, c, now)
440		if !ok {
441			c, full = c.Rewound(), true
442			p, _ = readTargets(targets, c, now)
443		}
444		metas, metaChanged := readMetas(targets[1:], infos, c)
445		return Delta{
446			valid: true, id: c.id, seq: c.seq, full: full,
447			changed:   full || p.changed || metaChanged,
448			sessionID: sanitizeLabel(files.ID),
449			files:     p.files, metas: metas, part: p.part, parentErr: p.parentErr,
450		}
451	}
