304	// mergeSkipping is merge, except that the entries named by skip are spilled.
305	func (t *table) mergeSkipping(o *table, skip map[msgKey]bool) {
306		for k, e := range o.entries {
307			if skip[k] {
308				t.spillEntry(e)
309				continue
310			}
311			_, had := t.entries[k]
312			t.put(k, e)
313			if !had && k.id == "" {
314				t.noID++
315			}
316		}
317		for agent, sp := range o.spill {
318			dst := t.spill[agent]
319			if dst == nil {
320				dst = &spill{}
321				t.spill[agent] = dst
322			}
323			dst.tokens = dst.tokens.Add(sp.tokens)
324			dst.messages += sp.messages
325			dst.partial += sp.partial
326			for _, m := range sp.models.list {
327				dst.models.add(m)
328			}
329		}
330		t.unreadable += o.unreadable
331		t.noUsage += o.noUsage
332		t.noMessageID += o.noMessageID
333		t.oversized += o.oversized
334		for name, s := range o.capped {
335			t.capped[name] = trimIssues(append(t.capped[name], s...), 2*maxFileIssuesPerFile)
336		}
337		t.stateIssues = append(t.stateIssues, o.stateIssues...)
338		for v, p := range o.versions {
339			t.noteVersion(v, p)
340		}
341	}
